import React, { useState, useEffect } from 'react';
import { createBooking } from '../utils/api';


const BookingForm = ({ slot, onBooked }) => {
  const [vehicleNumber, setVehicleNumber] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [cost, setCost] = useState(0);
  const [error, setError] = useState('');

  useEffect(() => {
    if (startTime && endTime) {
      const start = new Date(startTime);
      const end = new Date(endTime);
      if (start < end) {
        const diffInMs = end - start;
        const diffInHours = Math.ceil(diffInMs / (1000 * 60 * 60)); // Round up
        setCost(diffInHours * slot.hourlyRate);
      } else {
        setCost(0);
      }
    }
  }, [startTime, endTime, slot.hourlyRate]);

  const handleBooking = async () => {
    setError('');
    const now = new Date();

    if (!vehicleNumber.trim()) {
      setError('Vehicle number is required.');
      return;
    }

    const start = new Date(startTime);
    const end = new Date(endTime);

    if (start < now) {
      setError('Start time cannot be in the past.');
      return;
    }

    if (start >= end) {
      setError('Start time must be before end time.');
      return;
    }

    try {
      await createBooking({ vehicleNumber, startTime, endTime }, 1, slot.id); // Using userId = 1 for now
      onBooked();
    } catch (err) {
      const msg = err?.response?.data?.message || 'Booking failed.';
      setError(msg);
    }
  };

  return (
    <div>
      <h2>Book Slot {slot.slotNumber}</h2>
      {error && <div data-testid="form-error" style={{ color: 'red' }}>{error}</div>}
      <div>
        <label>Vehicle Number: </label>
        <input
          data-testid="vehicle-input"
          type="text"
          value={vehicleNumber}
          onChange={(e) => setVehicleNumber(e.target.value)}
        />
      </div>
      <div>
        <label>Start Time: </label>
        <input
          data-testid="start-time-input"
          type="datetime-local"
          value={startTime}
          onChange={(e) => setStartTime(e.target.value)}
        />
      </div>
      <div>
        <label>End Time: </label>
        <input
          data-testid="end-time-input"
          type="datetime-local"
          value={endTime}
          onChange={(e) => setEndTime(e.target.value)}
        />
      </div>
      <div data-testid="cost">Cost: ${cost.toFixed(2)}</div>
      <button data-testid="book-btn" onClick={handleBooking}>Book Now</button>
    </div>
  );
};

export default BookingForm;
